    return a < b ? a : b;
}
int mx(int a, int b)  {
    return a > b ? a : b;
}
int read(void)  {
    int x = 0;
    if (scanf("%d", &x) != 1) return 0;
    return x;
}
int readstr(int* a)  {
    char s[20001];
    if (scanf("%20000s", s) != 1) return 0;
    if (strcmp(s, "-") == 0) return 0;
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) a[i] = (unsigned char)s[i];
    return n;
}
void emit(int x)  {
    printf("%d ", x);
}
void emitstr(int* a, int n)  {
    if (n == 0) putchar('-');
    for (int i = 0; i < n; i++) putchar(a[i]);
    putchar(' ');
}
int main(void)  {
    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    int cnt = 0, i = 0, j = 0, n = 0;
    // 必须保留输入顺序；第一条之前没有任何鱼。
    n = read();
    for (i = 0; i < n; i += 1)  {
        a[i] = read();
    }
    for (i = 0; i < n; i += 1)  {
        // 每条鱼独立计数，不能累计上一条的答案。
        cnt = 0;
        for (j = 0; j < i; j += 1)  {
            if (a[j] < a[i])  {
                cnt = (cnt + 1);
            }
        }
        // 内层只统计 j<i 且 a[j]<a[i]，然后按输入顺序输出。
        emit(cnt);
    }
    return 0;
}

